  257→        <div class="upload-section">
  258→            <h2>上传照片</h2>
  259→            <p>记录你的大学美好时光</p>
  260→            <input type="file" id="fileInput" accept="image/*" multiple>
  261→            <button class="upload-btn" onclick="document.getElementById('fileInput').click()">选择照片</button>
  262→            <button class="upload-btn" onclick="uploadPhotos()">上传</button>
  263→        </div>
  264→        
  265→        <div class="gallery" id="gallery">
  266→            <!-- 照片将在这里显示 -->
  267→        </div>
  268→        
  269→        <!-- 详情模态框 -->
  270→        <div class="modal" id="photoModal">
  271→            <div class="modal-content">
  272→                <button class="modal-close" onclick="closeModal()">×</button>
  273→                <img src="" alt="" class="modal-img" id="modalImg">
  274→                <h3 class="modal-title" id="modalTitle"></h3>
  275→                <p class="modal-date" id="modalDate"></p>
  276→                <div class="modal-remark-section">
  277→                    <label class="modal-remark-label">备注：</label>
  278→                    <textarea class="modal-remark-input" id="modalRemark" placeholder="写下你的感受或备注..."></textarea>
  279→                    <button class="modal-save-btn" onclick="saveRemark()">保存备注</button>
  280→                </div>
  281→            </div>
  282→        </div>
