  284→    <script>
  285→        // 从 localStorage 加载已上传的照片
  286→        let uploadedPhotos = JSON.parse(localStorage.getItem('campusPhotos')) || [];
  287→        
  288→        // 从 localStorage 加载备注
  289→        let photoRemarks = JSON.parse(localStorage.getItem('photoRemarks')) || {};
  290→        
  291→        // 渲染照片
  292→        function renderPhotos() {
  293→            const gallery = document.getElementById('gallery');
  294→            gallery.innerHTML = '';
  295→            
  296→            uploadedPhotos.forEach((photo, index) => {
  297→                const photoCard = document.createElement('div');
  298→                photoCard.className = 'photo-card';
  299→                photoCard.onclick = () => openModal(index);
  300→                photoCard.innerHTML = `
  301→                    <img src="${photo.url}" alt="${photo.title}">
  302→                    <div class="photo-info">
  303→                        <h3>${photo.title}</h3>
  304→                        <p>${photo.date}</p>
  305→                        <button class="delete-btn" onclick="deletePhoto(${index})">删除</button>
  306→                    </div>
  307→                `;
  308→                gallery.appendChild(photoCard);
  309→            });
  310→        }
  311→        
  312→        // 上传照片
  313→        function uploadPhotos() {
  314→            const fileInput = document.getElementById('fileInput');
  315→            const files = fileInput.files;
  316→            
  317→            if (files.length === 0) {
  318→                alert('请选择要上传的照片');
  319→                return;
  320→            }
  321→            
  322→            Array.from(files).forEach(file => {
  323→                if (file.type.startsWith('image/')) {
  324→                    const reader = new FileReader();
  325→                    reader.onload = function(e) {
  326→                        const newPhoto = {
  327→                            url: e.target.result,
  328→                            title: file.name.replace(/\.[^/.]+$/, ''),
  329→                            date: new Date().toLocaleString('zh-CN', {
  330→                                year: 'numeric',
