  332→                                day: '2-digit',
  333→                                hour: '2-digit',
  334→                                minute: '2-digit'
  335→                            })
  336→                        };
  337→                        uploadedPhotos.push(newPhoto);
  338→                        savePhotos();
  339→                        renderPhotos();
  340→                    };
  341→                    reader.readAsDataURL(file);
  342→                }
  343→            });
  344→            
  345→            fileInput.value = '';
  346→        }
  347→        
  348→        // 保存照片到 localStorage
  349→        function savePhotos() {
  350→            localStorage.setItem('campusPhotos', JSON.stringify(uploadedPhotos));
  351→        }
  352→        
  353→        // 打开模态框
  354→        function openModal(index) {
  355→            const photo = uploadedPhotos[index];
