  357→            document.getElementById('modalTitle').textContent = photo.title;
  358→            document.getElementById('modalDate').textContent = photo.date;
  359→            document.getElementById('modalRemark').value = photoRemarks[index] || '';
  360→            document.getElementById('photoModal').classList.add('active');
  361→            document.getElementById('photoModal').dataset.index = index;
  362→        }
  363→        
  364→        // 关闭模态框
  365→        function closeModal() {
  366→            document.getElementById('photoModal').classList.remove('active');
  367→            delete document.getElementById('photoModal').dataset.index;
  368→        }
  369→        
  370→        // 保存备注
  371→        function saveRemark() {
  372→            const index = document.getElementById('photoModal').dataset.index;
  373→            photoRemarks[index] = document.getElementById('modalRemark').value;
  374→            localStorage.setItem('photoRemarks', JSON.stringify(photoRemarks));
  375→            alert('备注已保存！');
  376→        }
  377→        
  378→        // 点击模态框外部关闭
  379→        document.getElementById('photoModal').onclick = function(e) {
  380→            if (e.target === this) {
  381→                closeModal();
  382→            }
  383→        };
  384→        
  385→        // 删除照片
  386→        function deletePhoto(index) {
  387→            if (confirm('确定要删除这张照片吗？')) {
  388→                uploadedPhotos.splice(index, 1);
  389→                savePhotos();
  390→                renderPhotos();
  391→            }
  392→        }
  393→        
  394→        // 页面加载时渲染照片
  395→        renderPhotos();
  396→    </script>
