  114→    /**
  115→     * 将 ArrayBuffer 转换为 Base64
  116→     */
  117→    encodeImageData(arrayBuffer) {
  118→        const bytes = new Uint8Array(arrayBuffer);
  119→        let binary = '';
  120→        for (let i = 0; i < bytes.byteLength; i++) {
  121→            binary += String.fromCharCode(bytes[i]);
  122→        }
  123→        return btoa(binary);
  124→    }
