    1→/**
    2→ * DRM 加密系统 - 用于保护上传的照片
    3→ * 使用 AES-GCM 加密算法
    4→ */
    5→
    6→class DRMEncryptor {
    7→    constructor() {
    8→        this.algorithm = 'AES-GCM';
    9→        this.keyLength = 256; // 256 位密钥
   10→        this.version = '1.0';
   11→    }
   12→
   13→    /**
   14→     * 生成加密密钥
   15→     * 使用浏览器生成的随机数
   16→     */
   17→    generateKey() {
   18→        const arrayBuffer = new Uint8Array(this.keyLength / 8);
   19→        window.crypto.getRandomValues(arrayBuffer);
   20→        return btoa(String.fromCharCode(...arrayBuffer));
   21→    }
   22→
   23→    /**
   24→     * 从 base64 字符串解码密钥
   25→     */
   26→    decodeKey(keyBase64) {
   27→        const binaryString = atob(keyBase64);
   28→        const bytes = new Uint8Array(binaryString.length);
   29→        for (let i = 0; i < binaryString.length; i++) {
   30→            bytes[i] = binaryString.charCodeAt(i);
   31→        }
   32→        return bytes;
   33→    }
   34→
   35→    /**
   36→     * 加密图片数据
   37→     * @param {string} imageData - Base64 编码的图片数据
   38→     * @param {string} keyBase64 - Base64 编码的密钥
   39→     * @returns {object} 包含加密数据和元数据
   40→     */
   41→    encrypt(imageData, keyBase64) {
   42→        const key = this.decodeKey(keyBase64);
   43→        const iv = window.crypto.getRandomValues(new Uint8Array(12)); // 12 字节 IV
   44→        
   45→        try {
   46→            const encryptedContent = window.crypto.subtle.encrypt(
   47→                {
   48→                    name: this.algorithm,
   49→                    iv: iv
   50→                },
   51→                key,
   52→                this.decodeImageData(imageData)
   53→            );
   54→
   55→            const encryptedArray = new Uint8Array(encryptedContent);
   56→            const encryptedBase64 = btoa(String.fromCharCode(...Array.from(encryptedArray)));
   57→            
   58→            return {
   59→                encryptedData: encryptedBase64,
   60→                iv: Array.from(iv).map(b => b.toString(16).padStart(2, '0')).join(''),
   61→                timestamp: Date.now(),
   62→                version: this.version
   63→            };
   64→        } catch (error) {
   65→            console.error('加密失败:', error);
   66→            throw error;
   67→        }
   68→    }
   69→
   70→    /**
   71→     * 解密图片数据
   72→     * @param {string} encryptedData - Base64 编码的加密数据
   73→     * @param {string} ivHex - 十六进制格式的 IV
   74→     * @param {string} keyBase64 - Base64 编码的密钥
   75→     * @returns {string} 解密后的 Base64 图片数据
   76→     */
   77→    async decrypt(encryptedData, ivHex, keyBase64) {
   78→        const key = this.decodeKey(keyBase64);
   79→        const iv = new Uint8Array(ivHex.match(/.{1,2}/g).map(byte => parseInt(byte, 16)));
   80→        
   81→        try {
   82→            const encryptedArray = Uint8Array.from(atob(encryptedData), c => c.charCodeAt(0));
   83→            const decryptedContent = await window.crypto.subtle.decrypt(
   84→                {
   85→                    name: this.algorithm,
   86→                    iv: iv
   87→                },
   88→                key,
   89→                encryptedArray
   90→            );
   91→
   92→            const decryptedArray = new Uint8Array(decryptedContent);
   93→            const decryptedString = String.fromCharCode(...Array.from(decryptedArray));
   94→            return btoa(decryptedString);
   95→        } catch (error) {
   96→            console.error('解密失败:', error);
   97→            throw new Error('解密失败：密钥错误或数据损坏');
   98→        }
   99→    }
  100→
  101→    /**
  102→     * 将图片数据转换为 ArrayBuffer
  103→     */
  104→    decodeImageData(imageData) {
  105→        const base64 = imageData.split(',')[1];
  106→        const binaryString = atob(base64);
  107→        const bytes = new Uint8Array(binaryString.length);
  108→        for (let i = 0; i < binaryString.length; i++) {
  109→            bytes[i] = binaryString.charCodeAt(i);
  110→        }
  111→        return bytes;
  112→    }
  113→
  114→    /**
  115→     * 将 ArrayBuffer 转换为 Base64
  116→     */
  117→    encodeImageData(arrayBuffer) {
  118→        const bytes = new Uint8Array(arrayBuffer);
  119→        let binary = '';
  120→        for (let i = 0; i < bytes.byteLength; i++) {
  121→            binary += String.fromCharCode(bytes[i]);
  122→        }
  123→        return btoa(binary);
  124→    }
  125→
  126→    /**
  127→     * 验证加密数据版本
  128→     */
  129→    validateVersion(encryptedData) {
  130→        const version = encryptedData.version;
  131→        if (version !== this.version) {
  132→            console.warn(`版本不匹配：当前 ${this.version}, 加密数据 ${version}`);
  133→            return false;
  134→        }
  135→        return true;
  136→    }
  137→}
  138→
  139→/**
  140→ * 照片 DRM 管理器
  141→ */
  142→class PhotoDRMManager {
  143→    constructor() {
  144→        this.encryptor = new DRMEncryptor();
  145→        this.storageKey = 'campusPhotosDRM';
  146→        this.keyStorageKey = 'drmEncryptionKey';
  147→        this.init();
  148→    }
  149→
  150→    /**
  151→     * 初始化：检查或生成密钥
  152→     */
  153→    init() {
  154→        const storedKey = localStorage.getItem(this.keyStorageKey);
  155→        if (!storedKey) {
  156→            const newKey = this.encryptor.generateKey();
  157→            localStorage.setItem(this.keyStorageKey, newKey);
  158→            console.log('DRM 密钥已生成（首次使用）');
  159→        }
  160→    }
  161→
  162→    /**
  163→     * 获取当前密钥
  164→     */
  165→    getKey() {
  166→        return localStorage.getItem(this.keyStorageKey);
  167→    }
  168→
  169→    /**
  170→     * 上传加密照片
  171→     * @param {File} file - 图片文件
  172→     * @returns {object} 加密后的照片对象
  173→     */
  174→    async uploadPhoto(file) {
  175→        try {
  176→            // 读取文件为 Base64
  177→            const reader = new FileReader();
  178→            await new Promise((resolve, reject) => {
  179→                reader.onload = (e) => resolve(e.target.result);
  180→                reader.onerror = (e) => reject(new Error('读取文件失败'));
  181→                reader.readAsDataURL(file);
  182→            });
  183→
  184→            const imageData = reader.result;
  185→            const key = this.getKey();
  186→
  187→            // 加密图片
  188→            const encrypted = this.encryptor.encrypt(imageData, key);
  189→
  190→            // 创建照片对象
  191→            const photo = {
  192→                id: Date.now().toString(36) + Math.random().toString(36).substr(2),
  193→                originalName: file.name.replace(/\.[^/.]+$/, ''),
  194→                title: file.name.replace(/\.[^/.]+$/, ''),
  195→                date: new Date().toLocaleString('zh-CN', {
  196→                    year: 'numeric',
  197→                    month: '2-digit',
  198→                    day: '2-digit',
  199→                    hour: '2-digit',
  200→                    minute: '2-digit'
  201→                }),
  202→                encryptedData: encrypted,
  203→                encryptionKey: key,
  204→                version: this.encryptor.version
  205→            };
  206→
  207→            // 保存到本地存储
  208→            this.savePhotos([photo]);
  209→
  210→            return photo;
  211→        } catch (error) {
  212→            console.error('上传加密失败:', error);
  213→            throw error;
  214→        }
  215→    }
  216→
  217→    /**
  218→     * 渲染加密照片
  219→     */
  220→    renderPhotos() {
  221→        const gallery = document.getElementById('gallery');
  222→        if (!gallery) return;
  223→
  224→        gallery.innerHTML = '';
  225→
  226→        const photos = this.getPhotos();
  227→        if (photos.length === 0) {
  228→            gallery.innerHTML = '<p style="text-align:center;padding:20px;color:#ccc;">暂无照片</p>';
  229→            return;
  230→        }
  231→
  232→        photos.forEach((photo, index) => {
  233→            const photoCard = document.createElement('div');
  234→            photoCard.className = 'photo-card';
  235→            photoCard.innerHTML = `
  236→                <div class="photo-content">
  237→                    <img src="${photo.url}" alt="${photo.title}" onerror="this.style.display='none';this.nextElementSibling.style.display='block'">
  238→                    <div class="photo-error" style="display:none;text-align:center;padding:20px;">
  239→                        <p>需要授权才能查看</p>
  240→                        <button onclick="authorizePhoto('${photo.id}')">获取授权</button>
  241→                    </div>
  242→                </div>
  243→                <div class="photo-info">
  244→                    <h3>${photo.title}</h3>
  245→                    <p>${photo.date}</p>
  246→                    <button class="delete-btn" onclick="deletePhoto('${photo.id}')">删除</button>
  247→                </div>
  248→            `;
  249→            gallery.appendChild(photoCard);
  250→        });
  251→    }
  252→
  253→    /**
  254→     * 获取照片列表
  255→     */
  256→    getPhotos() {
  257→        return JSON.parse(localStorage.getItem(this.storageKey)) || [];
  258→    }
  259→
  260→    /**
  261→     * 保存照片列表
  262→     */
  263→    savePhotos(photos) {
  264→        localStorage.setItem(this.storageKey, JSON.stringify(photos));
  265→    }
  266→
  267→    /**
  268→     * 删除照片
  269→     */
  270→    deletePhoto(photoId) {
  271→        if (!confirm('确定要删除这张照片吗？')) return;
  272→
  273→        const photos = this.getPhotos();
  274→        const filteredPhotos = photos.filter(p => p.id !== photoId);
  275→        this.savePhotos(filteredPhotos);
  276→        
  277→        // 清除密钥（可选）
  278→        localStorage.removeItem(this.keyStorageKey);
  279→        
  280→        this.renderPhotos();
  281→    }
  282→
  283→    /**
  284→     * 授权查看照片
  285→     */
  286→    authorizePhoto(photoId) {
  287→        const photos = this.getPhotos();
  288→        const photo = photos.find(p => p.id === photoId);
  289→        
  290→        if (photo) {
  291→            // 解密并显示
  292→            const decrypted = this.encryptor.decrypt(
  293→                photo.encryptedData.encryptedData,
  294→                photo.encryptedData.iv,
  295→                photo.encryptionKey
  296→            );
  297→            
  298→            const blob = btoa(decrypted);
  299→            const byteString = atob(blob);
  300→            const buffer = new ArrayBuffer(byteString.length);
  301→            const intArray = new Uint8Array(buffer);
  302→            for (let i = 0; i < byteString.length; i++) {
  303→                intArray[i] = byteString.charCodeAt(i);
  304→            }
  305→            
  306→            const blobObject = new Blob([buffer], { type: 'image/jpeg' });
  307→            const url = URL.createObjectURL(blobObject);
  308→            
  309→            // 显示图片
  310→            const img = document.querySelector(`img[src*="${photoId}"]`);
  311→            if (img) {
  312→                img.src = url;
  313→                img.style.display = 'block';
  314→                img.nextElementSibling.style.display = 'none';
  315→            }
  316→        }
  317→    }
  318→
  319→    /**
  320→     * 导出所有照片（带 DRM）
  321→     */
  322→    exportPhotos() {
  323→        const photos = this.getPhotos();
  324→        const key = this.getKey();
  325→        
  326→        const exportData = {
  327→            version: this.encryptor.version,
  328→            timestamp: Date.now(),
  329→            photos: photos.map(p => ({
  330→                id: p.id,
  331→                title: p.title,
  332→                date: p.date,
  333→                encryptedData: p.encryptedData,
  334→                encryptionKey: p.encryptionKey
