  336→        };
  337→        
  338→        const blob = new Blob([JSON.stringify(exportData)], { type: 'application/json' });
  339→        const url = URL.createObjectURL(blob);
  340→        const a = document.createElement('a');
  341→        a.href = url;
  342→        a.download = `campus_photos_${new Date().toISOString().split('T')[0]}.drm`;
  343→        a.click();
  344→    }
  345→}
  346→
  347→// 全局实例
  348→window.drmManager = new PhotoDRMManager();

