  183→
  184→            const imageData = reader.result;
  185→            const key = this.getKey();
  186→
  187→            // 加密图片
  188→            const encrypted = this.encryptor.encrypt(imageData, key);
  189→
  190→            // 创建照片对象
  191→            const photo = {
  192→                id: Date.now().toString(36) + Math.random().toString(36).substr(2),
  193→                originalName: file.name.replace(/\.[^/.]+$/, ''),
